/**
 * <p>Appends a time zone offset in the form {@code +HHMM}, or {@code +HH:MM}
 * when {@code colon} is true.</p>
 *
 * <p>The sign is {@code '-'} for a negative offset and {@code '+'} otherwise.
 * The hour field is the number of whole hours in the magnitude of the offset.
 * The minute field is the value of {@link DateUtils#offsetMinuteField(int)}
 * for the offset. Both fields are written by
 * {@link DateFormatUtils#appendHourMinute(StringBuffer, int, int, boolean)}.</p>
 *
 * @param buffer  the buffer to append to, not null
 * @param offsetMillis  the offset from UTC in milliseconds, may be negative
 * @param colon  whether to put a {@code ':'} between the hour and minute fields
 */
public static void appendZoneOffset(final StringBuffer buffer, final int offsetMillis, final boolean colon) {
    int hours = offsetMillis / (60 * 60 * 1000);
    if (offsetMillis < 0) {
        buffer.append('-');
        hours = -hours;
    } else {
        buffer.append('+');
    }
    DateFormatUtils.appendHourMinute(buffer, hours, DateUtils.offsetMinuteField(offsetMillis), colon);
}

